function renderCausalGraph() {
  const canvas=document.querySelector('.graph-canvas'), detail=document.querySelector('.edge-card'); if (!canvas || !detail) return;
  const relations=data.relationships, nodes=[...new Set(relations.flatMap(r=>[r.from,r.to]))].map(indicatorOf).filter(Boolean);
  const positions=['left:5%;top:14%','left:5%;bottom:15%','left:42%;top:41%','right:5%;top:18%','right:5%;bottom:14%','left:25%;top:5%','left:41%;bottom:5%'];
  canvas.innerHTML=`<svg viewBox="0 0 800 410" preserveAspectRatio="none"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3 z" fill="#6e807c"/></marker></defs>${relations.map((r,i)=>`<path class="${r.evidenceType==='HYPOTHESIS'?'dashed':''}" data-rel="${r.id}" d="${['M145 105 C260 105,260 205,365 205','M145 305 C250 305,275 220,365 220','M460 205 C545 205,560 120,650 120','M460 215 C545 220,560 305,650 305'][i] || 'M460 215 C545 220,560 305,650 305'}" marker-end="url(#arrow)"/>`).join('')}</svg>${nodes.map((n,i)=>`<button class="g-node ${i===2?'focus':''}" style="${positions[i] || positions[3]}" data-node="${n.id}">${n.name}<small>${n.evidenceType} · ${n.period}</small></button>`).join('')}`;
  canvas.querySelectorAll('[data-node]').forEach(node=>node.onclick=()=>openIndicatorDetail(node.dataset.node));
  canvas.querySelectorAll('[data-rel]').forEach(path=>path.onclick=()=>openRelationshipDetail(path.dataset.rel));
  openRelationshipDetail(relations[0]?.id, true);
}
function openRelationshipDetail(relId, quiet=false) {
  const r=data.relationships.find(x=>x.id===relId), from=indicatorOf(r?.from), to=indicatorOf(r?.to), detail=document.querySelector('.edge-card'); if(!r||!detail)return;
  const strength=Math.round(r.strength*100), confidence=Math.round(r.confidence*100), supporting=r.supportingEvidence.length, opposing=r.contradictingEvidence.length;
  const evidenceLinks=[...r.supportingEvidence,...r.contradictingEvidence].filter(id=>data.evidence.some(e=>e.id===id));
  detail.innerHTML=`<p class="eyebrow">关系证据卡</p><h2>${from.name} → ${to.name}</h2>${badge(r.evidenceType)}<dl><dt>作用方向</dt><dd>${r.direction==='positive'?'正向':'负向'}</dd><dt>关系强度</dt><dd><div class="strength">${[1,2,3,4,5].map(n=>`<i class="${n>Math.ceil(r.strength*5)?'empty':''}"></i>`).join('')}</div> ${strength}%</dd><dt>研究置信度</dt><dd>${confidence}%</dd><dt>预计影响滞后</dt><dd>${r.lag.min}—${r.lag.max} 个月</dd></dl><hr><b>作用机制</b><p>${r.mechanism}</p><div class="evidence-count"><span>支持证据 ${supporting}</span><span>反对证据 ${opposing}</span></div><button class="secondary" data-target="evidence">查看相关证据</button>`;
  if (evidenceLinks.length) detail.insertAdjacentHTML('beforeend',`<div class="relation-evidence-links">${evidenceLinks.map(id=>`<button data-relation-evidence="${id}">打开证据：${data.evidence.find(e=>e.id===id).title}</button>`).join('')}</div>`);
  detail.querySelector('[data-target]').onclick=()=>{appState.evidenceFilter='全部';showView('evidence');renderEvidenceEngine();};
  detail.querySelectorAll('[data-relation-evidence]').forEach(button=>button.onclick=()=>openEvidenceDetail(button.dataset.relationEvidence));
  if (!quiet) detail.scrollIntoView({behavior:'smooth',block:'nearest'});
}

function cityScore(c) { return Math.round((100-c.policyExecutionFriction + 100-c.institutionalReplicationFriction + c.startupActivity + c.privateEconomyVitality + c.talentAttraction + c.governmentDigitalization + c.financingEnvironment + c.industrialEcosystem) / 8); }
function renderCityResearch() {
  const section=byId('cities'); if(!section)return;
  section.classList.remove('placeholder');
  const cities=[...data.cities].sort((a,b)=>cityScore(b)-cityScore(a));
  section.innerHTML=`<div class="view-intro"><p class="eyebrow">City institutional competitiveness</p><h1>城市制度研究</h1><p>PEF 与 IRF 均为研究模型演示值，不能视为官方营商环境排名。PEF 越低越好；IRF 越低越易复制成熟制度。</p></div><div class="panel city-table"><div class="demo-strip">DEMO MODEL · 非官方排名 · 所有评分待真实研究数据验证</div><table><thead><tr><th>城市</th><th>PEF ↓</th><th>IRF ↓</th><th>创业活跃度</th><th>民企活力</th><th>人才吸引</th><th>研究模型综合值</th><th>证据</th></tr></thead><tbody>${cities.map(c=>`<tr><td><b>${c.name}</b></td><td>${c.policyExecutionFriction}</td><td>${c.institutionalReplicationFriction}</td><td>${c.startupActivity}</td><td>${c.privateEconomyVitality}</td><td>${c.talentAttraction}</td><td><b>${cityScore(c)}</b></td><td>${badge(c.evidenceType)}</td></tr>`).join('')}</tbody></table></div>`;
}
function researchModuleCards(category, title, intro) {
  const indicators=data.indicators.filter(x=>x.category===category);
  return `<div class="view-intro"><p class="eyebrow">Research module</p><h1>${title}</h1><p>${intro}</p></div><div class="module-grid">${indicators.map(item=>{const source=sourceOf(item.sourceId);return `<button class="panel mini-indicator" data-indicator="${item.id}"><div><p class="eyebrow">${item.name}</p><b>${item.value}<small>${item.unit}</small></b></div><div>${demoFlag(item.status)}${badge(item.evidenceType)}</div><p>${source.name} · ${item.period}</p><small>数据质量 ${qualityLabel(qualityScore(item.dataQuality))} · 置信度 ${Math.round(item.confidence*100)}%</small></button>`}).join('')}</div>`;
}
function renderModules() {
  const property=byId('property'), household=byId('household');
  property.classList.remove('placeholder'); property.innerHTML=researchModuleCards('property','房地产系统','从价格、成交、库存、土地到按揭信贷，观察反馈关系；所有数值均为 MOCK。');
  household.classList.remove('placeholder'); household.innerHTML=researchModuleCards('household','居民部门','按资产负债表、收入预期与消费行为分层研究；样本调查不代表全国人口。');
  [property,household].forEach(section=>section.querySelectorAll('[data-indicator]').forEach(card=>card.onclick=()=>openIndicatorDetail(card.dataset.indicator)));
}
function renderScenario() {
  const section=byId('scenarios'); if(!section)return;
  const current=data.scenarios.find(x=>x.id===appState.scenarioId)||data.scenarios[0], result=runScenario(current);
  section.innerHTML=`<div class="view-intro"><p class="eyebrow">Rule-based scenario engine</p><h1>情景推演</h1><p>情景不是预测：仅在预设条件下，按有限因果关系传播变化。</p></div><div class="scenario-grid"><section class="panel scenario-selector"><p class="eyebrow">选择框架</p>${data.scenarios.map(s=>`<button class="scenario ${s.id===current.id?'active':''}" data-scenario="${s.id}"><span>${s.code}</span><b>${s.name}</b><small>${s.description}</small></button>`).join('')}</section><section class="panel scenario-result"><div class="demo-strip">DEMO SCENARIO · 不构成现实预测、投资或政策建议</div><p class="eyebrow">${current.code} · 条件性推演</p><h2>${current.name}</h2><div class="scenario-chain">${Object.entries(current.changes).map(([id,value])=>`<span>${indicatorOf(id)?.name || id} ${value>0?'+':''}${value}%</span>`).join('<i>→</i>')}</div><div class="impact-grid"><div><b>直接影响</b><p>${result.direct || '当前无直接冲击。'}</p></div><div><b>二阶影响</b><p>${result.second || '未发现可传播的关系。'}</p></div><div><b>三阶影响</b><p>${result.third || '需补充更多关系后计算。'}</p></div><div><b>预计滞后 / 置信度</b><p>${result.lag} · ${Math.round(result.confidence*100)}%</p></div></div><button class="primary" id="scenarioExplain">查看传播依据</button></section></div>`;
  section.querySelectorAll('[data-scenario]').forEach(button=>button.onclick=()=>{appState.scenarioId=button.dataset.scenario;renderScenario()});
  byId('scenarioExplain').onclick=()=>showView('causal');
}
function runScenario(scenario) {
  const direct=Object.entries(scenario.changes).map(([id,v])=>`${indicatorOf(id)?.name || id} ${v>0?'+':''}${v}%`).join('；');
  const affected=data.relationships.filter(r=>Object.keys(scenario.changes).includes(r.from));
  const second=affected.map(r=>`${indicatorOf(r.to)?.name}：${r.direction==='positive'?'同向':'反向'}变化（关系强度 ${Math.round(r.strength*100)}%）`).join('；');
  const third=affected.flatMap(first=>data.relationships.filter(r=>r.from===first.to)).map(r=>`${indicatorOf(r.to)?.name}：存在后续传导可能`).join('；');
  const maxLag=affected.reduce((max,r)=>Math.max(max,r.lag.max),0);
  const confidence=affected.length?affected.reduce((sum,r)=>sum+r.confidence,0)/affected.length*scenario.confidence:scenario.confidence;
  return {direct,second,third,lag:maxLag?`预计 ${maxLag} 个月内出现主要二阶影响`:'未设置传导滞后',confidence};
}
function renderEvidence() {
  const section=byId('evidence'); if(!section)return;
  section.classList.remove('placeholder');
  section.innerHTML=`<div class="view-intro"><p class="eyebrow">Evidence engine</p><h1>证据库与研究透明度</h1><p>结论 → 推理 → 数据 → 来源。不同证据状态不能互相替代。</p></div><div class="evidence-layout"><section class="panel"><div class="panel-title"><div><p class="eyebrow">来源目录</p><h2>${data.sources.length} 个预置来源</h2></div><span class="demo-flag">MOCK CATALOG</span></div><div class="source-list">${data.sources.map(s=>`<div><b>${s.name}</b><span>${s.type}</span><small>信任等级：${s.trustLevel}</small></div>`).join('')}</div></section><section class="panel transparency"><p class="eyebrow">Research Transparency</p><h2>研究辅助，不替代判断</h2><p>民生OS是一套研究辅助系统。系统中的内容可能包含事实、估算、推断、假设、预测、情景和观点，所有内容应根据证据等级区别理解。</p><p>任何模拟结果不构成投资、政策或经济决策建议。</p><div class="state-legend">${['FACT','ESTIMATE','INFERENCE','HYPOTHESIS','FORECAST','SCENARIO','OPINION'].map(badge).join('')}</div></section></div>`;
}
function saveLocalResearch() { window.MinshengPersistence?.save({research:data.research,evidence:data.evidence,inbox:data.inbox,indicators:data.indicators,records:data.records,rawPayloads:data.rawPayloads,batches:data.batches,auditLog:data.auditLog,canonicalOverrides:data.canonicalOverrides,sourceDocuments:data.sourceDocuments,files:data.files,methodologies:data.methodologies,methodologyEvents:data.methodologyEvents,documentSections:data.documentSections,documentTables:data.documentTables}); }
function statusText(status) { return ({OPEN:'开放研究',HYPOTHESIS:'研究假设',SUPPORTED:'支持中',WEAKENED:'反证增强',DISPUTED:'存在争议',REJECTED:'已否定',INCONCLUSIVE:'待补数据',ARCHIVED:'已归档'})[status] || status; }
