  section.innerHTML=`<div class="view-intro"><p class="eyebrow">Research memory engine</p><h1>研究记忆</h1><p>保留支持证据、反证、替代解释和判断变化；不会用新结论覆盖旧判断。</p></div><div class="research-status-grid">${statuses.slice(0,6).map(s=>`<div class="status-stat"><span>${statusText(s)}</span><b>${counts[s]}</b></div>`).join('')}<div class="status-stat"><span>待补数据</span><b>${counts.INCONCLUSIVE + data.research.filter(r=>(r.requiredData||[]).length>0).length}</b></div></div><div class="panel research-list"><div class="panel-title"><div><p class="eyebrow">研究问题</p><h2>${data.research.length} 条可追溯研究</h2></div><button class="primary" id="createResearch">+ 新建研究问题</button></div><div class="research-list-body">${data.research.map(r=>{const x=window.MinshengConfidence.explain(r,data.evidence);return `<button class="research-row" data-research="${r.id}"><div>${badge(r.status)}<b>${r.title}</b><span>${r.currentConclusion}</span></div><div class="research-score"><b>${r.confidence===null?'数据不足':Math.round(r.confidence*100)+'%'}</b><small>支持 ${x.supportScore.toFixed(2)} · 反证 ${x.contradictScore.toFixed(2)}</small></div><span class="chev">→</span></button>`}).join('')}</div></div>`;
