function resetDemo(){if(!confirm('将清除本地研究修改并恢复 DEMO 数据，是否继续？'))return;window.MinshengPersistence.clear();data.research=window.MinshengPersistence.clone(baseData.research);data.evidence=window.MinshengPersistence.clone(baseData.evidence);data.inbox=window.MinshengPersistence.clone(baseData.inbox);data.indicators=window.MinshengPersistence.clone(baseData.indicators);renderEvidenceEngine();renderResearchWorkspace();renderResearchNotes();}
function importJsonFile(event){const file=event.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{const parsed=window.MinshengImportExport.parseJson(reader.result);if(parsed.errors.length){alert(parsed.errors.join('\n'));return}const incoming=parsed.value, errors=[], collections=[['evidence',window.MinshengImportExport.validateEvidence],['research',window.MinshengImportExport.validateResearch],['indicators',x=>x?.id?null:'指标必须包含 id。']];collections.forEach(([key,validator])=>(incoming[key]||[]).forEach(item=>{const target=data[key];if(!Array.isArray(target))return;if(target.some(x=>x.id===item.id))errors.push(`${key}: 重复 id ${item.id}`);const err=validator(item);if(err)errors.push(`${key}: ${err}`)}));if(errors.length){alert('导入失败：\n'+errors.join('\n'));return}collections.forEach(([key])=>{if(Array.isArray(incoming[key]))data[key].push(...incoming[key])});saveLocalResearch();renderEvidenceEngine();renderResearchWorkspace();alert('JSON 导入完成。');};reader.readAsText(file);}
function importCsvFile(event){const file=event.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{const result=window.MinshengImportExport.parseCsv(reader.result);if(result.errors.length){alert('CSV 导入失败：\n'+result.errors.join('\n'));return}openDialog(`<p class="eyebrow">CSV 预览</p><h2>确认导入指标</h2><p class="detail-copy">将导入 ${result.rows.length} 条；以下仅预览前 10 行。</p><pre class="csv-preview">${JSON.stringify(result.rows.slice(0,10),null,2)}</pre><button class="primary" id="confirmCsv">确认导入</button>`);byId('confirmCsv').onclick=()=>{const duplicate=result.rows.find(row=>data.indicators.some(x=>x.id===row.id));if(duplicate){alert('导入失败：重复 id '+duplicate.id);return}data.indicators.push(...result.rows.map(row=>({...row,value:row.value===''?null:row.value,previousValue:null,category:'imported',module:'导入指标',frequency:'unknown',sourceName:sourceOf(row.sourceId).name,confidence:null,direction:'unknown',status:'LOCAL',updatedAt:window.MinshengResearchMemory.today(),description:'CSV 手动导入',interpretation:'数据待核验。',tags:['CSV 导入'],dataQuality:{completeness:null,freshness:null,reliability:null,comparability:null}})));saveLocalResearch();byId('modal').classList.remove('show');alert('CSV 指标导入完成。');};};reader.readAsText(file);}
