function audit(action,entityType,entityId,before,after,reason='') { const entry=window.MinshengAuditLog.create(action,entityType,entityId,before,after,reason);window.MinshengAuditLog.add(data.auditLog,entry);return entry; }
function canonicalRecord(indicatorId,period) { const indicator=indicatorOf(indicatorId), targetPeriod=period||indicator?.period; return window.MinshengProvenance.canonical(data.records,data.sources,indicatorId,targetPeriod,data.canonicalOverrides?.[`${indicatorId}|${targetPeriod}`]); }
function hydrateIndicatorsFromRecords() { data.indicators.forEach(indicator=>{const record=canonicalRecord(indicator.id);if(!record)return;indicator.value=record.convertedValue??record.value;indicator.unit=record.convertedUnit??record.unit;indicator.period=record.period;indicator.updatedAt=record.releaseDate;indicator._recordId=record.id;});data.evidence.forEach(e=>{if(e.evidenceType==='FACT'&&!e.dataRecordIds?.length)e.dataRecordIds=data.records.filter(r=>e.relatedIndicators.includes(r.indicatorId)).map(r=>r.id);}); }
