function renderDataIntake() { const section=byId('intake');if(!section)return;const conflicts=data.records.filter(r=>r.qualityFlags?.includes('SOURCE_CONFLICT')).length;section.innerHTML=`<div class="view-intro"><p class="eyebrow">Data Intake & Provenance</p><h1>数据接入</h1><p>导入前映射字段、校验口径与单位、检查重复/修订/来源冲突；不会静默覆盖既有数字。</p></div><section class="panel intake-steps"><div><b>01</b><span>选择 CSV / JSON</span></div><i>→</i><div><b>02</b><span>字段映射与来源</span></div><i>→</i><div><b>03</b><span>预览与冲突检查</span></div><i>→</i><div><b>04</b><span>生成批次与血缘</span></div></section><div class="intake-actions"><button class="primary" id="intakeCsv">导入 CSV 数据记录</button><button class="secondary" id="intakeJson">导入 JSON 数据记录</button><input id="intakeCsvInput" hidden type="file" accept=".csv,text/csv"><input id="intakeJsonInput" hidden type="file" accept="application/json"></div><div class="intake-grid"><section class="panel"><p class="eyebrow">最近导入</p><h2>导入批次</h2><div class="batch-list">${data.batches.slice().reverse().map(b=>`<div><b>${b.fileName}</b><span>${b.fileType} · ${fmtDate(b.importedAt?.slice(0,10))}</span><small>记录 ${b.recordCount} · 接收 ${b.acceptedCount} · 拒绝 ${b.rejectedCount}</small><em>${b.status}</em></div>`).join('')||'<p>暂无导入批次</p>'}</div></section><section class="panel"><p class="eyebrow">需要关注</p><h2>导入状态</h2><div class="intake-summary"><span>记录总数 <b>${data.records.length}</b></span><span>来源冲突 <b>${conflicts}</b></span><span>指标草稿 <b>${data.indicators.filter(i=>i.status==='DRAFT').length}</b></span><span>审计事件 <b>${data.auditLog.length}</b></span></div><p class="detail-copy">缺失值使用 <code>null</code> 与缺失原因；不会以 0 代替未知。</p></section></div>`;byId('intakeCsv').onclick=()=>byId('intakeCsvInput').click();byId('intakeJson').onclick=()=>byId('intakeJsonInput').click();byId('intakeCsvInput').onchange=e=>prepareCsvIntake(e.target.files[0]);byId('intakeJsonInput').onchange=e=>prepareRecordJsonIntake(e.target.files[0]); }
function genericCsv(text) { const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/).filter(Boolean);if(lines.length<2)return {headers:[],rows:[],errors:['CSV 至少需要标题行和一条数据。']};const split=line=>line.split(',').map(v=>v.trim().replace(/^"|"$/g,''));const headers=split(lines.shift());return {headers,rows:lines.map(split).map(cells=>Object.fromEntries(headers.map((h,i)=>[h,cells[i]??'']))),errors:[]}; }
function mappedDefault(header) { const h=header.toLowerCase();if(/指标|indicator|name/.test(h))return 'indicator';if(/报告期|period|date|月份/.test(h))return 'period';if(/数值|value|数值/.test(h))return 'value';if(/单位|unit/.test(h))return 'unit';if(/频率|frequency/.test(h))return 'frequency';if(/来源|source/.test(h))return 'sourceId';return 'ignore'; }
function prepareCsvIntake(file) { if(!file)return;const reader=new FileReader();reader.onload=()=>{const parsed=genericCsv(reader.result);if(parsed.errors.length){alert(parsed.errors.join('\n'));return}openMappingDialog(parsed,file.name);};reader.readAsText(file); }
function openMappingDialog(parsed,fileName) { const targets=['ignore','indicator','period','value','unit','frequency','sourceId'];openDialog(`<p class="eyebrow">CSV 字段映射</p><h2>将原始字段映射到数据记录</h2><p class="detail-copy">${fileName} · ${parsed.rows.length} 行。未知指标将在预览中标记为 DRAFT，不会自动进入正式指标库。</p><div class="mapping-list">${parsed.headers.map(h=>`<label>${h}<select data-map="${h}">${targets.map(t=>`<option value="${t}" ${mappedDefault(h)===t?'selected':''}>${t}</option>`).join('')}</select></label>`).join('')}</div><label>默认来源<select id="mappingSource">${data.sources.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select></label><button class="primary" id="previewMappedCsv">预览与校验</button>`);byId('previewMappedCsv').onclick=()=>{const map=Object.fromEntries(parsed.headers.map(h=>[h,document.querySelector(`[data-map="${CSS.escape(h)}"]`).value]));previewMappedRecords(parsed.rows,map,byId('mappingSource').value,fileName);}; }
function makeRecordCandidate(row,map,sourceId,index) { const read=target=>Object.entries(map).find(([,v])=>v===target)?.[0], rawIndicator=row[read('indicator')]?.trim(), existing=data.indicators.find(i=>i.id===rawIndicator||i.name===rawIndicator), draft=existing||{id:`draft_${rawIndicator?.toLowerCase().replace(/[^a-z0-9]+/g,'_')||index}`,name:rawIndicator||'未命名指标',status:'DRAFT',category:'draft',definition:'由 CSV 导入创建的指标草稿，需人工确认。',preferredUnit:row[read('unit')]||null,frequency:row[read('frequency')]||'monthly',observationType:'index',seasonalAdjustment:false,nominalReal:'nominal',cumulative:false,preferredSourceId:sourceId,alternativeSourceIds:[],methodologyNotes:'',comparabilityNotes:'',startPeriod:null,discontinued:false}; const unit=row[read('unit')]||draft.preferredUnit||null,frequency=row[read('frequency')]||draft.frequency||'monthly',conversion=window.MinshengProvenance.normalizeUnit(row[read('value')],unit,draft.preferredUnit||unit), flags=[];if(conversion.flag)flags.push(conversion.flag);if(row[read('value')]==='')flags.push('MISSING');if(!existing)flags.push('DRAFT_INDICATOR');const record={id:`record_import_${Date.now()}_${index}`,seriesId:`LOCAL.${sourceId.toUpperCase()}.${draft.id.toUpperCase()}.${frequency.toUpperCase()}.${draft.observationType?.toUpperCase()||'INDEX'}`,indicatorId:draft.id,value:conversion.value??null,unit:conversion.unit||unit,period:row[read('period')]||null,frequency,observationType:draft.observationType||'index',transformation:'raw',sourceId:row[read('sourceId')]||sourceId,sourceDocumentId:null,releaseDate:window.MinshengResearchMemory.today(),importedAt:new Date().toISOString(),evidenceType:'FACT',status:'LOCAL',revision:0,previousRecordId:null,qualityFlags:flags,originalValue:conversion.originalValue??row[read('value')]??null,originalUnit:conversion.originalUnit??unit,convertedValue:conversion.value??null,convertedUnit:conversion.unit??unit,conversionRule:conversion.rule||null,missingReason:row[read('value')]===''?'not_available':null,provenance:{importBatchId:null,originalFile:null,originalSheet:null,originalRow:index+2,originalColumn:read('value')||null,originalField:read('value')||null,parser:'csv_field_mapping',transformationHistory:conversion.rule?[conversion.rule]:[]},notes:''};return {record,draft,conversion}; }
function previewMappedRecords(rows,map,sourceId,fileName) { const proposed=rows.map((row,index)=>makeRecordCandidate(row,map,sourceId,index));const allIndicators=[...data.indicators,...proposed.filter(x=>!data.indicators.some(i=>i.id===x.draft.id)).map(x=>x.draft)], errors=[], conflicts=[];proposed.forEach(p=>{const e=[...window.MinshengProvenance.validate(p.record,allIndicators,data.sources),p.conversion.error].filter(Boolean);if(e.length)errors.push({p,e});const c=window.MinshengProvenance.classifyConflict(p.record,data.records);if(c.type!=='none')conflicts.push({p,c});p.conflict=c;});const accepted=proposed.length-errors.length-conflicts.filter(x=>x.c.type==='duplicate').length;openDialog(`<p class="eyebrow">导入预览</p><h2>确认数据记录</h2><div class="preview-counts"><span>总记录 <b>${proposed.length}</b></span><span>可导入 <b>${Math.max(0,accepted)}</b></span><span>警告 <b>${conflicts.length}</b></span><span>错误 <b>${errors.length}</b></span></div><p class="detail-copy">同来源同期间数值变化视为修订冲突；不同来源数值不同会同时保留并标记来源冲突。</p>${conflicts.length?`<label>修订冲突处理<select id="revisionAction"><option value="preserve">保留旧值（跳过新值）</option><option value="revise">接受新值作为修订</option></select></label><div class="conflict-list">${conflicts.slice(0,8).map(x=>`<p><b>${x.p.record.indicatorId} / ${x.p.record.period}</b>：${x.c.type}</p>`).join('')}</div>`:''}${errors.length?`<div class="error-list">${errors.slice(0,8).map(x=>`<p>${x.p.record.indicatorId||'未知指标'}：${x.e.join('；')}</p>`).join('')}</div>`:''}<pre class="csv-preview">${JSON.stringify(proposed.slice(0,10).map(x=>x.record),null,2)}</pre><button class="primary" id="commitDataImport">确认正式导入</button>`);byId('commitDataImport').onclick=()=>commitRecordImport({proposed,errors,fileName,sourceId,revisionAction:byId('revisionAction')?.value||'preserve'}); }
function commitRecordImport({proposed,errors,fileName,sourceId,revisionAction}) { const invalid=new Set(errors.map(x=>x.p));const batch={id:`batch_${Date.now()}`,importedAt:new Date().toISOString(),fileName,fileType:'csv',sourceId,recordCount:proposed.length,acceptedCount:0,rejectedCount:0,status:'completed',warnings:[],errors:[]};const drafts=[];proposed.forEach(p=>{if(invalid.has(p)){batch.rejectedCount++;batch.errors.push('Schema validation failed');return}const conflict=window.MinshengProvenance.classifyConflict(p.record,data.records);if(conflict.type==='duplicate'){batch.rejectedCount++;batch.warnings.push(`duplicate: ${p.record.indicatorId} ${p.record.period}`);return}if(conflict.type==='revision_conflict'&&revisionAction!=='revise'){batch.rejectedCount++;batch.warnings.push(`revision preserved: ${p.record.indicatorId} ${p.record.period}`);return}if(!data.indicators.some(i=>i.id===p.draft.id)){drafts.push(p.draft);audit('CREATE_INDICATOR','indicator',p.draft.id,null,p.draft,'CSV unknown indicator created as DRAFT');}p.record.provenance.importBatchId=batch.id;p.record.provenance.originalFile=fileName;if(conflict.type==='revision_conflict'){const prior=conflict.matches.sort((a,b)=>b.revision-a.revision)[0];p.record.revision=prior.revision+1;p.record.previousRecordId=prior.id;p.record.qualityFlags.push('REVISED');audit('REVISE','data_record',p.record.id,prior,p.record,'CSV value changed for same source/indicator/period');}else if(conflict.type==='source_conflict'){p.record.qualityFlags.push('SOURCE_CONFLICT');conflict.matches.forEach(r=>{if(!r.qualityFlags.includes('SOURCE_CONFLICT'))r.qualityFlags.push('SOURCE_CONFLICT')});audit('IMPORT','data_record',p.record.id,null,p.record,'Different source value retained as source conflict');}else audit('IMPORT','data_record',p.record.id,null,p.record,'CSV import');data.records.push(p.record);batch.acceptedCount++;});data.indicators.push(...drafts.filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i));data.batches.push(batch);audit('IMPORT','import_batch',batch.id,null,batch,`Imported ${batch.acceptedCount} records from ${fileName}`);saveLocalResearch();hydrateIndicatorsFromRecords();renderDataIntake();renderDataHealth();renderIndicators();byId('modal').classList.remove('show');alert(`导入完成：接收 ${batch.acceptedCount}，拒绝 ${batch.rejectedCount}。`); }
function prepareRecordJsonIntake(file) { if(!file)return;const reader=new FileReader();reader.onload=()=>{const parsed=window.MinshengImportExport.parseJson(reader.result);if(parsed.errors.length){alert(parsed.errors.join('\n'));return}const records=parsed.value.dataRecords||parsed.value.records;if(!Array.isArray(records)){alert('JSON 必须包含 dataRecords 或 records 数组。');return}const errors=[];records.forEach(r=>errors.push(...window.MinshengProvenance.validate(r,data.indicators,data.sources)));if(errors.length){alert('JSON 数据记录校验失败：\n'+[...new Set(errors)].join('\n'));return}previewMappedRecords(records.map(r=>({indicator:r.indicatorId,period:r.period,value:r.value,unit:r.unit,frequency:r.frequency,sourceId:r.sourceId})),{indicator:'indicator',period:'period',value:'value',unit:'unit',frequency:'frequency',sourceId:'sourceId'},records[0]?.sourceId||'pboc',file.name);};reader.readAsText(file); }
function renderSources() { const section=byId('sources');if(!section)return;const sources=data.sources.map(source=>{const records=data.records.filter(r=>r.sourceId===source.id&&!r.deleted),latest=records.map(r=>r.period).sort().at(-1)||'—',indicators=[...new Set(records.map(r=>r.indicatorId))];return {source,records,latest,indicators};});section.innerHTML=`<div class="view-intro"><p class="eyebrow">Source registry & Data Lineage</p><h1>来源与数据血缘</h1><p>当前采用值可追溯到 Data Record、导入批次、原始字段、转换规则与来源机构。</p></div><div class="source-cards">${sources.map(({source,records,latest,indicators})=>`<button class="panel source-card" data-source="${source.id}"><div><p class="eyebrow">${source.type}</p><h2>${source.name}</h2></div><span class="demo-flag">${source.qualityConfigStatus||'DEMO'}</span><div class="source-stats"><span>数据记录 <b>${records.length}</b></span><span>最新期间 <b>${latest}</b></span><span>关联指标 <b>${indicators.length}</b></span></div><small>权威 ${Math.round(source.authority*100)}% · 透明度 ${Math.round(source.transparency*100)}%</small></button>`).join('')}</div><section class="panel audit-panel"><div class="panel-title"><div><p class="eyebrow">Audit Log</p><h2>近期审计记录</h2></div></div><div class="audit-list">${data.auditLog.slice().reverse().slice(0,10).map(a=>`<div><b>${a.action}</b><span>${a.entityType} · ${a.entityId}</span><small>${a.reason||'—'} · ${fmtDate(a.timestamp.slice(0,10))}</small></div>`).join('')||'<p>暂无本地审计操作；初始 MOCK 记录未计入操作日志。</p>'}</div></section>`;section.querySelectorAll('[data-source]').forEach(button=>button.onclick=()=>openSourceDetail(button.dataset.source)); }
function openSourceDetail(id) { const source=sourceOf(id),records=data.records.filter(r=>r.sourceId===id&&!r.deleted);openDialog(`<p class="eyebrow">来源详情 · DEMO 配置</p><h2>${source.name}</h2><div class="detail-grid"><div><b>类型</b><span>${source.type}</span></div><div><b>数据记录</b><span>${records.length}</span></div><div><b>权威配置</b><span>${Math.round(source.authority*100)}%</span></div><div><b>方法透明度</b><span>${Math.round(source.methodologyClarity*100)}%</span></div></div><h3>关联数据记录</h3><div class="source-records">${records.map(r=>`<button data-record-open="${r.id}">${r.indicatorId} · ${r.period} · ${r.convertedValue??'数据不足'} ${r.convertedUnit||r.unit}</button>`).join('')||'<p>暂无</p>'}</div>`);byId('modal').querySelectorAll('[data-record-open]').forEach(b=>b.onclick=()=>openRecordDetail(b.dataset.recordOpen)); }
function openRecordDetail(id) { const r=data.records.find(x=>x.id===id);if(!r)return;const indicator=indicatorOf(r.indicatorId),batch=data.batches.find(b=>b.id===r.provenance?.importBatchId),document=data.sourceDocuments.find(d=>d.id===r.sourceDocumentId),canonical=canonicalRecord(r.indicatorId,r.period),revisions=data.records.filter(x=>x.indicatorId===r.indicatorId&&x.period===r.period&&x.sourceId===r.sourceId).sort((a,b)=>a.revision-b.revision);openDialog(`<p class="eyebrow">Data Lineage</p><h2>${indicator?.name||r.indicatorId} · ${r.period}</h2><div class="detail-value">${r.convertedValue??'数据不足'} <small>${r.convertedUnit||r.unit||''}</small></div><p>${r.id===canonical?.id?'<span class="metric-chip green">当前采用值</span>':'<span class="metric-chip neutral">备选值</span>'} ${r.status==='MOCK'?'<span class="demo-flag">MOCK</span>':''}</p><div class="lineage-flow"><span>指标<br><b>${indicator?.name||r.indicatorId}</b></span><i>↓</i><span>记录<br><b>${r.id}</b></span><i>↓</i><span>来源<br><b>${sourceOf(r.sourceId).name}</b></span><i>↓</i><span>批次<br><b>${batch?.id||'迁移/手动'}</b></span></div><div class="detail-grid"><div><b>观察期 / 发布日</b><span>${r.period} / ${fmtDate(r.releaseDate)}</span></div><div><b>频率 / 类型</b><span>${r.frequency} / ${r.observationType}</span></div><div><b>转换</b><span>${r.transformation}${r.conversionRule?' · '+r.conversionRule:''}</span></div><div><b>原始字段</b><span>${r.provenance?.originalField||'—'}</span></div><div><b>质量标记</b><span>${r.qualityFlags?.join(' · ')||'—'}</span></div><div><b>统计口径</b><span>${indicator?.methodologyNotes||'未登记'}</span></div></div><h3>修订历史</h3><div class="revision-list">${revisions.map(x=>`<div><b>r${x.revision}</b><span>${x.convertedValue??'数据不足'} ${x.convertedUnit||x.unit} · ${fmtDate(x.releaseDate)}</span></div>`).join('')}</div>${r.id!==canonical?.id?'<button class="secondary" id="setCanonical">将此记录设为当前采用值</button>':''}`);if(byId('setCanonical'))byId('setCanonical').onclick=()=>{data.canonicalOverrides[`${r.indicatorId}|${r.period}`]=r.id;audit('CHANGE_CANONICAL','data_record',r.id,canonical,r,'Manual canonical record selection');saveLocalResearch();hydrateIndicatorsFromRecords();renderIndicators();renderDataIntake();openRecordDetail(r.id);}; }
function openIndicatorDetail(indicatorId) { const item=indicatorOf(indicatorId);if(!item)return;const records=data.records.filter(r=>r.indicatorId===item.id&&!r.deleted).sort((a,b)=>a.period.localeCompare(b.period)),record=canonicalRecord(item.id),evidence=data.evidence.filter(e=>e.relatedIndicators.includes(item.id)),research=data.research.filter(r=>evidence.some(e=>e.relatedResearch.includes(r.id))),relations=data.relationships.filter(r=>r.from===item.id||r.to===item.id);openDialog(`<p class="eyebrow">指标与时间序列 ${demoFlag(item.status)}</p><h2>${item.name}</h2><div class="detail-value">${record?.convertedValue??'数据不足'} <small>${record?.convertedUnit||item.unit||''}</small></div><p>${badge(record?.evidenceType||item.evidenceType)} ${record?`当前记录：${record.id}`:'暂无 Data Record'}</p><div class="series-list">${records.map(r=>`<button data-record-open="${r.id}"><span>${r.period}</span><b>${r.convertedValue??'数据不足'} ${r.convertedUnit||r.unit||''}</b><small>${sourceOf(r.sourceId).name} · r${r.revision}${r.qualityFlags?.length?' · '+r.qualityFlags.join(','):''}</small></button>`).join('')||'<p>数据不足</p>'}</div><div class="indicator-links"><b>相关证据 ${evidence.length}</b>${evidence.map(e=>`<button data-indicator-evidence="${e.id}">${e.title}</button>`).join('')||'<p>暂无</p>'}<b>相关研究 ${research.length}</b>${research.map(r=>`<button data-indicator-research="${r.id}">${r.title}</button>`).join('')||'<p>暂无</p>'}<b>相关因果关系 ${relations.length}</b><p>${relations.map(r=>`${indicatorOf(r.from)?.name} → ${indicatorOf(r.to)?.name}`).join('<br>')||'暂无'}</p></div>`);const modal=byId('modal');modal.querySelectorAll('[data-record-open]').forEach(b=>b.onclick=()=>openRecordDetail(b.dataset.recordOpen));modal.querySelectorAll('[data-indicator-evidence]').forEach(b=>b.onclick=()=>openEvidenceDetail(b.dataset.indicatorEvidence));modal.querySelectorAll('[data-indicator-research]').forEach(b=>b.onclick=()=>openResearchDetail(b.dataset.indicatorResearch)); }
function hydrateIndicatorsFromRecords() { window.MinshengOutliers?.apply(data.records);data.indicators.forEach(indicator=>{const record=canonicalRecord(indicator.id);if(!record)return;indicator.value=record.convertedValue??record.value;indicator.unit=record.convertedUnit??record.unit;indicator.period=record.period;indicator.updatedAt=record.releaseDate;indicator._recordId=record.id;});data.evidence.forEach(e=>{if(e.evidenceType==='FACT'&&!e.dataRecordIds?.length)e.dataRecordIds=data.records.filter(r=>e.relatedIndicators.includes(r.indicatorId)).map(r=>r.id);}); }
function exportSnapshot(){window.MinshengImportExport.download('minsheng-os-v04-snapshot.json',{version:'0.4',exportedAt:new Date().toISOString(),research:data.research,evidence:data.evidence,indicators:data.indicators,dataRecords:data.records,importBatches:data.batches,canonicalOverrides:data.canonicalOverrides,auditLog:data.auditLog,localState:{inbox:data.inbox}});}
function resetDemo(){if(!confirm('将清除本地研究与数据接入修改，并恢复 DEMO / MOCK 数据，是否继续？'))return;window.MinshengPersistence.clear();['research','evidence','inbox','indicators','records','batches','auditLog','canonicalOverrides'].forEach(key=>data[key]=window.MinshengPersistence.clone(baseData[key]));hydrateIndicatorsFromRecords();renderEvidenceEngine();renderResearchWorkspace();renderResearchNotes();renderDataHealth();renderDataIntake();renderSources();renderIndicators();}
function openEvidenceDetail(id) {const e=data.evidence.find(x=>x.id===id);if(!e)return;const records=(e.dataRecordIds||[]).map(id=>data.records.find(r=>r.id===id)).filter(Boolean);openDialog(`<p class="eyebrow">证据详情 ${e.status==='MOCK'?'<span class="demo-flag">MOCK</span>':''}</p><h2>${e.title}</h2><div class="detail-copy">${e.summary}</div><p>${badge(e.evidenceType)} <span class="stance ${e.stance.toLowerCase()}">${e.stance}</span></p><div class="detail-grid"><div><b>来源</b><span>${sourceOf(e.sourceId).name}</span></div><div><b>来源类型</b><span>${e.sourceType}</span></div><div><b>发布日期 / 数据期</b><span>${fmtDate(e.publishedAt)} / ${e.dataPeriod||'数据不足'}</span></div><div><b>置信度 / 重要度</b><span>${Math.round(e.confidence*100)}% / ${Math.round(e.importance*100)}%</span></div><div><b>新鲜度</b><span>${freshnessLabel(e.publishedAt)}</span></div><div><b>来源链接</b><span>${e.url?e.url:'暂无来源链接'}</span></div></div><h3>关联数据记录（${records.length}）</h3><div class="source-records">${records.map(r=>`<button data-record-open="${r.id}">${r.indicatorId} · ${r.period} · ${r.convertedValue??'数据不足'} ${r.convertedUnit||r.unit}</button>`).join('')||'<p>暂无数据记录；事实证据可在后续人工关联。</p>'}</div><p class="detail-copy"><b>关联研究：</b>${e.relatedResearch.map(id=>data.research.find(r=>r.id===id)?.title||id).join('；')||'—'}<br><b>备注：</b>${e.notes||'—'}</p>`);byId('modal').querySelectorAll('[data-record-open]').forEach(b=>b.onclick=()=>openRecordDetail(b.dataset.recordOpen));}
function createV05Views(){const intakeNav=document.querySelector('.nav-item[data-view="intake"]');if(intakeNav&&!document.querySelector('.nav-item[data-view="library"]'))intakeNav.insertAdjacentHTML('afterend','<button class="nav-item" data-view="library"><i>▤</i>资料库</button><button class="nav-item" data-view="methodologies"><i>⌁</i>统计口径</button>');if(!byId('library'))byId('scenarios').insertAdjacentHTML('beforebegin','<section id="library" class="view"></section><section id="methodologies" class="view"></section>');}
function v05Migrate(){data.records.forEach(r=>{r.deleted??=false;r.deletedAt??=null;r.deleteReason??=null;r.sourceDocumentId??=(r.sourceId==='pboc'?'doc_pboc_2026_07_financial_stats':r.sourceId==='nbs'?'doc_nbs_2026_07_property_stats':null);r.methodologyId??=(r.indicatorId==='household_deposit'?'method_pboc_household_deposit_v1':r.indicatorId==='second_hand_home_price'?'method_nbs_property_price_v2':null);});data.evidence.forEach(e=>{e.sourceDocumentId??=(e.sourceId==='pboc'?'doc_pboc_2026_07_financial_stats':null);e.locator??={page:null,section:'',table:'',row:'',column:'',paragraph:'',quote:null};e.independenceGroup??=(e.sourceDocumentId||`${e.sourceId}_${e.publishedAt}`);});data.sourceDocuments.forEach(d=>{d.deleted??=false;d.deletedAt??=null;d.deleteReason??=null;});}
function renderLibrary(){const section=byId('library');if(!section)return;const query=(appState.documentQuery||'').toLowerCase(),type=appState.documentType||'全部',docs=data.sourceDocuments.filter(d=>!d.deleted&&(type==='全部'||d.documentType===type)&&(!query||[d.title,d.sourceId,...(d.tags||[]),...(d.relatedIndicatorIds||[])].join(' ').toLowerCase().includes(query)));section.innerHTML=`<div class="view-intro"><p class="eyebrow">Source Document Intelligence</p><h1>资料库</h1><p>文件登记不等于证据。文档、数据记录、证据和研究保持独立且可双向追溯。</p></div><div class="library-tools"><input id="documentSearch" placeholder="搜索标题、标签、机构或关联指标" value="${appState.documentQuery||''}"><select id="documentType"><option>全部</option>${['statistical_release','policy_report','research_report','dataset','methodology_document','investment_bank_report','academic_paper','other'].map(x=>`<option ${type===x?'selected':''}>${x}</option>`).join('')}</select><button class="primary" id="registerDocument">+ 登记资料</button></div><div class="library-layout"><section class="panel document-list">${docs.map(d=>`<button data-document="${d.id}"><span class="doc-type">${d.documentType}</span><b>${d.title}</b><small>${sourceOf(d.sourceId).name} · 发布 ${fmtDate(d.publicationDate)} · v${d.version}</small><em>${d.status}</em></button>`).join('')||'<p>无匹配资料。</p>'}</section><aside class="panel library-note"><p class="eyebrow">Document discipline</p><h2>资料定位</h2><p>原始 URL、附件、页码、表格与引文不存在时，系统显示“未登记”，不会编造。</p><div class="doc-coverage"><span>资料 ${data.sourceDocuments.filter(d=>!d.deleted).length}</span><span>附件元数据 ${data.files.filter(f=>!f.deleted).length}</span><span>有文档记录 ${data.records.filter(r=>r.sourceDocumentId&&!r.deleted).length}</span></div></aside></div>`;byId('documentSearch').oninput=e=>{appState.documentQuery=e.target.value;renderLibrary()};byId('documentType').onchange=e=>{appState.documentType=e.target.value;renderLibrary()};byId('registerDocument').onclick=openDocumentForm;section.querySelectorAll('[data-document]').forEach(b=>b.onclick=()=>openDocumentDetail(b.dataset.document));}
function openDocumentForm(){openDialog(`<p class="eyebrow">Document Intake</p><h2>登记资料元数据</h2><form id="documentForm"><label>文件标题<input name="title" required></label><div class="form-two"><label>来源<select name="sourceId">${data.sources.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select></label><label>文件类型<select name="documentType">${['statistical_release','policy_report','research_report','dataset','methodology_document','other'].map(x=>`<option>${x}</option>`).join('')}</select></label></div><div class="form-two"><label>发布日期<input name="publicationDate" type="date"></label><label>数据期开始<input name="dataPeriodStart" type="date"></label></div><label>关联指标（以逗号分隔 ID）<input name="indicators" placeholder="household_deposit,mortgage_growth"></label><label>选择附件（仅登记元数据）<input name="attachment" type="file" accept=".pdf,.csv,.json,.txt,.html,.htm,.xlsx,.xls"></label><button class="primary">保存资料登记</button></form>`);byId('documentForm').onsubmit=e=>{e.preventDefault();const form=e.target,v=Object.fromEntries(new FormData(form)),file=form.attachment.files[0],id=`doc_local_${Date.now()}`,doc={id,title:v.title,sourceId:v.sourceId,sourceType:sourceOf(v.sourceId).type,documentType:v.documentType,publicationDate:v.publicationDate||null,dataPeriodStart:v.dataPeriodStart||null,dataPeriodEnd:null,language:'zh-CN',status:'DRAFT',originalUrl:'',localFileId:null,version:1,supersedesDocumentId:null,supersededByDocumentId:null,relatedIndicatorIds:v.indicators.split(',').map(x=>x.trim()).filter(Boolean),relatedEvidenceIds:[],relatedDataRecordIds:[],relatedResearchIds:[],methodologyIds:[],tags:[],quality:{completeness:null,machineReadable:null,methodologyClarity:null,citationQuality:null},createdAt:window.MinshengResearchMemory.today(),updatedAt:window.MinshengResearchMemory.today(),notes:'本地资料登记；附件仅保存元数据。',deleted:false};if(file){const metadata={id:`file_${Date.now()}`,fileName:file.name,fileType:(file.name.split('.').pop()||'').toLowerCase(),mimeType:file.type||null,size:file.size,importedAt:new Date().toISOString(),checksum:null,storageType:'metadata_only',status:'ACTIVE',sourceDocumentId:id,notes:''};const err=window.MinshengFileRegistry.validate(metadata),dup=window.MinshengFileRegistry.duplicate(data.files,metadata);if(err||dup){alert(err||'存在相同文件元数据，未登记。');return}data.files.push(metadata);doc.localFileId=metadata.id;}data.sourceDocuments.push(doc);audit('CREATE_DOCUMENT','source_document',id,null,doc,'Manual document intake');saveLocalResearch();renderLibrary();renderSources();byId('modal').classList.remove('show');};}
function openDocumentDetail(id){const d=data.sourceDocuments.find(x=>x.id===id),file=data.files.find(f=>f.id===d?.localFileId),records=data.records.filter(r=>r.sourceDocumentId===id),evidence=data.evidence.filter(e=>e.sourceDocumentId===id),methods=data.methodologies.filter(m=>m.sourceDocumentIds?.includes(id)),versions=data.sourceDocuments.filter(x=>x.id===id||x.supersedesDocumentId===id||x.supersededByDocumentId===id);if(!d)return;openDialog(`<p class="eyebrow">Source Document Detail</p><h2>${d.title}</h2><p><span class="metric-chip ${d.status==='ACTIVE'?'green':'neutral'}">${d.status}</span> <span class="demo-flag">${d.status==='MOCK'?'MOCK':'LOCAL METADATA'}</span></p><div class="detail-grid"><div><b>机构 / 类型</b><span>${sourceOf(d.sourceId).name} / ${d.documentType}</span></div><div><b>发布日期</b><span>${fmtDate(d.publicationDate)}</span></div><div><b>数据覆盖期</b><span>${d.dataPeriodStart||'未登记'} — ${d.dataPeriodEnd||'未登记'}</span></div><div><b>版本</b><span>v${d.version}</span></div><div><b>本地附件</b><span>${file?file.fileName+'（metadata_only）':'未登记'}</span></div><div><b>原始 URL</b><span>${d.originalUrl||'未登记'}</span></div></div><h3>关联指标</h3><p class="detail-copy">${d.relatedIndicatorIds.map(x=>indicatorOf(x)?.name||x).join('；')||'未登记'}</p><h3>此文件产生的数据</h3><div class="source-records">${records.map(r=>`<button data-record-open="${r.id}">${r.indicatorId} · ${r.period} · ${r.convertedValue??'数据不足'} ${r.convertedUnit||r.unit}</button>`).join('')||'<p>未登记 Data Record</p>'}</div><h3>关联研究证据</h3><div class="source-records">${evidence.map(e=>`<button data-evidence-open="${e.id}">${e.title}</button>`).join('')||'<p>未登记 Evidence</p>'}</div><h3>统计口径</h3><p class="detail-copy">${methods.map(m=>m.title).join('；')||'未登记'}</p><h3>文件版本历史</h3><p class="detail-copy">${versions.map(v=>`${v.id} · v${v.version} · ${v.status}`).join('<br>')}</p><div class="modal-actions">${d.deleted?'<button class="secondary" id="restoreDocument">恢复资料</button>':'<button class="secondary danger" id="archiveDocument">归档/删除资料</button>'}<button class="primary close">关闭</button></div>`);const modal=byId('modal');modal.querySelectorAll('[data-record-open]').forEach(b=>b.onclick=()=>openRecordDetail(b.dataset.recordOpen));modal.querySelectorAll('[data-evidence-open]').forEach(b=>b.onclick=()=>openEvidenceDetail(b.dataset.evidenceOpen));modal.querySelector('.close').onclick=()=>modal.classList.remove('show');if(byId('archiveDocument'))byId('archiveDocument').onclick=()=>{const reason=prompt('请输入归档/删除原因：');if(!reason)return;window.MinshengSoftDelete.mark(d,reason);d.status='DELETED';audit('ARCHIVE_DOCUMENT','source_document',d.id,null,d,reason);saveLocalResearch();renderLibrary();byId('modal').classList.remove('show');};if(byId('restoreDocument'))byId('restoreDocument').onclick=()=>{window.MinshengSoftDelete.restore(d);d.status='ARCHIVED';audit('UPDATE_DOCUMENT','source_document',d.id,null,d,'Restore document');saveLocalResearch();renderLibrary();openDocumentDetail(d.id);};}
function renderMethodologies(){const section=byId('methodologies');if(!section)return;section.innerHTML=`<div class="view-intro"><p class="eyebrow">Methodology Intelligence</p><h1>统计口径</h1><p>口径变化不等于数值错误；可比性为 BREAK 时，前后数据不能默认连成连续序列。</p></div><div class="method-grid">${data.indicators.map(i=>{const methods=data.methodologies.filter(m=>m.indicatorIds.includes(i.id)),events=data.methodologyEvents.filter(e=>e.indicatorId===i.id);if(!methods.length)return '';return `<button class="panel method-card" data-method-indicator="${i.id}"><p class="eyebrow">${i.name}</p><h2>${methods.find(m=>m.status==='ACTIVE')?.title||'未登记当前口径'}</h2><p>${events.some(e=>e.comparabilityImpact==='BREAK')?'<span class="break-badge">统计口径发生变化 · BREAK</span>':'<span class="metric-chip green">可比性无已知断点</span>'}</p><small>历史版本 ${methods.length} · 变更事件 ${events.length}</small></button>`}).join('')||'<p>暂无统计口径登记。</p>'}</div>`;section.querySelectorAll('[data-method-indicator]').forEach(b=>b.onclick=()=>openMethodologyDetail(b.dataset.methodIndicator));}
function openMethodologyDetail(indicatorId){const indicator=indicatorOf(indicatorId),methods=data.methodologies.filter(m=>m.indicatorIds.includes(indicatorId)).sort((a,b)=>(a.validFrom||'').localeCompare(b.validFrom||'')),events=data.methodologyEvents.filter(e=>e.indicatorId===indicatorId);openDialog(`<p class="eyebrow">Methodology Timeline</p><h2>${indicator?.name||indicatorId}</h2>${events.some(e=>e.comparabilityImpact==='BREAK')?'<div class="method-warning">统计口径发生变化：前后数据可能不可直接比较。</div>':''}<div class="method-timeline">${methods.map(m=>`<div><b>${m.validFrom||'未登记'} — ${m.validTo||'至今'}</b><span>${m.title} · ${m.status}</span><small>${m.comparabilityImpact} · ${m.definition}</small></div>`).join('')}</div><h3>口径变更事件</h3>${events.map(e=>`<div class="method-event"><b>${e.effectivePeriod} · ${e.changeType}</b><span>${e.comparabilityImpact} / ${e.severity}</span><p>${e.description}</p><small>来源文件：${e.sourceDocumentId||'未登记'}</small></div>`).join('')||'<p>未登记变更事件。</p>'}`);}
